class Counter {
    @Volatile
    private var counter = 0

    fun bad() {
        counter++
    }
}

class Counter {
    @Volatile
    private var counter = 0

    fun bad() {
        counter--
    }
}

class Counter {
    @Volatile
    private var count = 0

    fun bad() {
        count += 1
    }
}

import java.util.concurrent.atomic.AtomicInteger

class Counter {
    private val atomicCounter = AtomicInteger()

    fun good() {
        atomicCounter.incrementAndGet()
    }
}

class FlagHolder {
    @Volatile
    private var flag = false

    fun good() {
        flag = true
    }
}

class Holder {
    @Volatile
    private var cached: String? = null

    fun get(): String {
        return cached!!
    }
}

class Counter {
    @Volatile
    private var count = 0

    fun dec() {
        --count
    }

    fun inc() {
        ++count
    }
}

class A {
    @Volatile
    private var count = 0

    fun f() {
        var count = 0
        count++
    }
}

class A {
    @Volatile
    private var i = 0

    fun f() {
        for (i in 1..3) {
            var i = 0
            i++
        }
    }
}

class A {
    @Volatile
    private var count = 0

    fun f() {
        this.count++
    }
}

class Outer {
    @Volatile
    private var count = 0

    inner class Inner {
        fun f() {
            count++
        }
    }
}

class A {
    companion object {
        @Volatile
        private var count = 0

        fun f() {
            count++
        }
    }
}

class A {
    @Volatile
    private var count = 0

    fun f(xs: List<Int>) {
        xs.forEach { count++ }
    }
}

class A {
    @Volatile
    private var count = 0

    fun f() {
        count += 1
        this.count -= 1
    }
}

class Other { var count = 0 }

class A {
    @Volatile
    private var count = 0

    fun f(o: Other) {
        o.count += 1
        o.count++
        ++o.count
    }
}
